<?php $o=query('SELECT * FROM orders WHERE id=?',[(int)($_GET['id']??0)])->fetch();if(!$o):http_response_code(404);?><h1>Narudžba ne postoji.</h1><?php else:$preparing=in_array($o['status'],['new','preparing'],true);?>
<div class="page-title"><div><p class="eyebrow">OBRADA NARUDŽBE</p><h1>Narudžba #<?=$o['id']?></h1><p><?=e($o['created_at'])?> · <?=e($o['customer_name'])?></p></div><div class="action-group"><a class="btn secondary" href="?page=orders">Sve narudžbe</a><?php if(can('print')):?><a class="btn" href="?page=print&id=<?=$o['id']?>">Štampaj list za slanje</a><?php endif;?></div></div>
<div class="order-status-strip"><div><small>OTPREMA</small><span class="status-badge status-<?=e($o['status'])?>"><?=e(orderStatus($o['status']))?></span></div><div><small>NAPLATA</small><span class="status-badge status-<?=e($o['payment_status'])?>"><?=e(paymentLabel($o['payment_status']))?></span></div><div><small>LAGER</small><strong><?=$o['inventory_state']==='untracked'?'Bez praćenja lagera':($o['inventory_state']==='reserved'?'Na lageru · rezervisano':($o['inventory_state']==='deducted'?'Razduženo · izvan lagera':($o['inventory_state']==='released'?'Rezervacija oslobođena / roba vraćena':'Stari zapis · provjeriti stanje')))?></strong></div><div><small>OBRADA</small><strong><?=isOrderSettled($o)?'Razduženo i naplaćeno':($preparing?'Čeka potvrdu otpreme':($o['payment_status']==='unpaid'&&in_array($o['inventory_state'],['deducted','untracked'],true)?'Čeka naplatu':'Pogledajte evidenciju'))?></strong></div></div>
<?php if($preparing&&$o['payment_status']==='paid'&&$o['inventory_state']!=='untracked'):?><div class="notice warning"><strong>Naplata je evidentirana, ali otprema nije potvrđena.</strong> Roba je još rezervisana na vašem lageru. Potvrdite slanje ili ličnu predaju u obrascu ispod.</div><?php endif;if($o['status']==='completed'||$o['inventory_state']==='legacy'):?><div class="notice warning">Ovo je zapis ranije verzije. Status, količine, datum slanja i kurir nisu automatski rekonstruisani. Provjerite stvarnu otpremu i karticu lagera prije novih promjena.</div><?php endif;?>
<div class="admin-columns"><section class="panel"><h2>Primalac i narudžba</h2><p><strong><?=e($o['customer_name'])?></strong><br><?=e($o['address'])?><br><?=e($o['city'])?><br><?=e($o['phone'])?><br><?=e($o['email'])?></p><p><?=nl2br(e((string)$o['note']))?></p><hr><p>Uslovi kupčeve narudžbe: <?=nl2br(e((string)$o['shipping_terms']))?> · <?=e(deliveryPayerLabel($o))?></p><p>Odabrana dostava: <?=e($o['shipping_method'])?> · <?=money((float)$o['shipping_cost'])?></p><?php if($o['planned_delivery_id']):?><div class="notice"><strong>Pripremljena dostava: <?=e($o['planned_delivery_name'])?></strong><br>Dogovoreni trošak kurira: <?=money((float)$o['planned_delivery_cost'])?> · <?=e(deliveryPayers()[$o['planned_delivery_payer']]??'')?><br><?=nl2br(e($o['planned_delivery_terms']))?></div><?php endif;?><p>Kurir / izvršilac: <strong><?=e($o['dispatch_method']==='personal'?'Lična predaja':($o['courier_name']??'Nije evidentiran'))?></strong><br>Broj pošiljke: <?=e((string)($o['tracking_number']?:'Nije unesen'))?><br>Datum otpreme: <?=e((string)($o['dispatched_at']??'Nije evidentiran'))?></p><p><?=nl2br(e((string)$o['dispatch_note']))?></p><h2>Ukupno: <?=money((float)$o['total'])?></h2></section>
<section class="panel"><h2>Potvrda otpreme</h2><?php if($preparing&&can('shipping')):?>
<?php if(deliveryType($o)==='pickup'):?><p class="notice">Kupac je odabrao lično preuzimanje. Trošak isporuke je 0,00 KM. Nije potrebna kurirska služba.</p><?php else:require __DIR__.'/shipment-prepare.php';endif;?><details class="secondary-operation" <?=deliveryType($o)==='pickup'?'open':''?>><summary><?=deliveryType($o)==='pickup'?'Potvrda ličnog preuzimanja':'Lična predaja kupcu umjesto slanja'?></summary><p class="field-help"><?=deliveryType($o)==='pickup'?'Potvrdite predaju narudžbe kupcu. Nema dodatnog troška dostave.':'Lična predaja ne mijenja ugovoreni iznos narudžbe i ranije odabranu cijenu dostave.'?></p><?php startForm('status',(int)$o['id']);?><input type="hidden" name="status" value="handed_over"><?php textField('dispatch_note','Kome je predano, gdje i po kojem dokumentu');?><button>Potvrdi ličnu predaju i razduži lager</button></form></details>
<?php elseif(in_array($o['status'],['shipped','delivered','completed'],true)&&can('shipping')&&$o['dispatch_method']!=='personal'):?><p>Pošiljka je otpremljena. Dopuna podataka ne umanjuje lager ponovo.</p><?php startForm('shipment',(int)$o['id']);field('courier_name','Kurirska služba',$o['courier_name']??'');field('tracking_number','Broj pošiljke',$o['tracking_number']??'','text',false);textField('dispatch_note','Razlog dopune / ispravke podataka');?><button>Spremi podatke pošiljke</button></form>
<?php else:?><p class="field-help"><?=!can('shipping')?'Nemate dozvolu za otpremu.':'Za ovu narudžbu nema nove otpreme.'?></p><?php endif;?></section></div>
<div class="admin-columns"><section class="panel"><h2>Naplata / povrat novca</h2><p>Način plaćanja: <?=e(deliveryPaymentLabel($o))?></p><p class="field-help">Ova radnja evidentira novac. Ne potvrđuje slanje, ne mijenja kurira i ne umanjuje zalihe.</p><?php if(can('payments')&&!in_array($o['status'],['cancelled','returned'],true)):startForm('payment',(int)$o['id']);selectField('payment_status','Radnja',$o['payment_status']==='paid'?['refunded'=>'Evidentiraj povrat novca']:['paid'=>'Evidentiraj naplatu']);field('note','Dokument / obrazloženje');?><button><?=$o['payment_status']==='paid'?'Potvrdi povrat novca':'Potvrdi naplatu'?></button></form><?php else:?><p>Nema dostupne radnje naplate za ovaj račun.</p><?php endif;?></section>
<section class="panel"><h2>Dostava, otkazivanje i povrat robe</h2><?php $opts=[];foreach(transitions($o['status']) as $s)if(!in_array($s,['preparing','shipped','handed_over'],true)&&(can('shipping')||!in_array($s,['delivered','returned'],true)))$opts[$s]=orderStatus($s);if($opts):startForm('status',(int)$o['id']);selectField('status','Radnja',$opts);textField('dispatch_note','Obavezno obrazloženje / dokument');?><button>Potvrdi promjenu</button></form><p class="field-help">Naplaćena narudžba prvo zahtijeva povrat novca. Otkazivanje oslobađa rezervaciju, a povrat otpremljene robe vraća količinu na lager jednom.</p><?php else:?><p>Nema dostupne promjene.</p><?php endif;?></section></div>
<section class="panel"><h2>Stavke narudžbe</h2><div class="table-scroll"><table><thead><tr><th>Artikal</th><th>Količina</th><th>Jedinična cijena</th><th>Obrada lagera</th></tr></thead><tbody><?php foreach(query('SELECT * FROM order_items WHERE order_id=?',[$o['id']])->fetchAll() as $i):?><tr><td><?=e($i['product_name'])?></td><td><?=$i['quantity']?></td><td><?=money((float)$i['unit_price'])?></td><td><?=$o['inventory_state']==='untracked'?'Bez praćenja lagera':($o['inventory_state']==='reserved'?'Rezervisano':($o['inventory_state']==='deducted'?'Razduženo':($o['inventory_state']==='released'?'Vraćeno / oslobođeno':'Stari zapis')))?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Historija otpreme i naplate</h2><div class="table-scroll"><table><thead><tr><th>Datum</th><th>Radnja</th><th>Dokument / obrazloženje</th><th>Operater</th></tr></thead><tbody><?php foreach(query("SELECT a.*,u.name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id WHERE a.entity_id=? AND (a.action LIKE 'order.%' OR a.action IN ('payment.paid','payment.refunded')) ORDER BY a.id DESC",[$o['id']])->fetchAll() as $a):?><tr><td><?=e($a['created_at'])?></td><td><?=e(activityLabel($a['action']))?></td><td><?=e(activityDetails($a))?></td><td><?=e($a['name']??'Kupac / sistem')?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
